-- PostgreSQL relational foundation. Every tenant-owned relation includes tenant_id.
CREATE TABLE tenants (id text PRIMARY KEY, name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), auth_subject text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,auth_subject), UNIQUE(tenant_id,id));
CREATE TABLE developers (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE agents (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), developer_id text NOT NULL, name text NOT NULL, identity_type text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,developer_id) REFERENCES developers(tenant_id,id));
CREATE TABLE connected_accounts (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), user_id text NOT NULL, provider text NOT NULL, origin text NOT NULL, display_label text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE TABLE credentials (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), account_id text NOT NULL, credential_type text NOT NULL, ciphertext bytea NOT NULL, wrapped_dek bytea NOT NULL, key_version text NOT NULL, record_version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES connected_accounts(tenant_id,id));
CREATE TABLE delegations (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), user_id text NOT NULL, agent_id text NOT NULL, account_id text NOT NULL, scopes text[] NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,agent_id) REFERENCES agents(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES connected_accounts(tenant_id,id));
CREATE TABLE grants (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), user_id text NOT NULL, agent_id text NOT NULL, account_id text NOT NULL, origin text NOT NULL, scopes text[] NOT NULL, task_id text, policy_version integer NOT NULL, approval_id text, issued_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,agent_id) REFERENCES agents(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES connected_accounts(tenant_id,id), CHECK(expires_at>issued_at));
CREATE INDEX grants_active_lookup ON grants(tenant_id,agent_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE approvals (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), grant_id text NOT NULL, requested_by text NOT NULL, decision text NOT NULL CHECK(decision IN ('pending','approved','denied')), decided_by text, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,grant_id) REFERENCES grants(tenant_id,id));
CREATE TABLE executions (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), grant_id text NOT NULL, operation text NOT NULL, status text NOT NULL, safe_result_code text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, FOREIGN KEY(tenant_id,grant_id) REFERENCES grants(tenant_id,id));
CREATE TABLE audit_events (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), actor_type text NOT NULL, actor_id text NOT NULL, event_type text NOT NULL, resource_ref text, decision text, correlation_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_tenant_time ON audit_events(tenant_id,created_at DESC);
-- Never write plaintext credentials, tokens, cookies, or authentication headers to audit metadata.
